#!/bin/sh
# Builds run_CreatingKhoe.do from the verbatim copy CreatingKhoe.do (all 67 lines unchanged) plus
# environment header (E1-E3) and extraction footer (X1). See PATCHES.md.
cd "$(dirname "$0")"
{
cat <<'H'
* S2 run file for P07_FG. GENERATED by build_runs.sh -- do not edit.
version 13
clear all
set more off
do "../../tools/paths.do"
capture log close
log using "logs/run_CreatingKhoe.log", text replace
use "$DATA/P07_FG/original/14 FG Missing People/missingpeople.dta", clear
* ==== begin CreatingKhoe.do lines 1-67 (verbatim) ====
H
sed -n '1,67p' CreatingKhoe.do
cat <<'F'

* ==== end verbatim; X1: extraction only (Table 1 sums on the in-memory sample) ====
gen _csd = district<4
tabstat cattlekhoe slaves slavemales, by(year) stat(sum n) format(%12.4f)
tabstat cattlekhoe slaves slavemales if _csd==1, by(year) stat(sum n) format(%12.4f)
tabstat cattlekhoe slaves slavemales if district==4, by(year) stat(sum n) format(%12.4f)
tabstat cattlekhoe slaves slavemales, by(district) stat(sum n) format(%12.4f)
log close
F
} > run_CreatingKhoe.do

# run_productivity.do: productivity.do (Fourie Slaves, 173 lines, verbatim) on slaveproductivity.dta.
# esttab "using" writes to the working directory -> cd output/ (E5).
{
cat <<'H'
* S2 run file (P07_FG, productivity.do). GENERATED by build_runs.sh -- do not edit.
version 13
clear all
set more off
sysdir set PLUS "`c(pwd)'/ado/plus"
sysdir set PERSONAL "`c(pwd)'/ado/personal"
do "../../tools/paths.do"
capture log close
log using "logs/run_productivity.log", text replace
use "$DATA/P07_FG/original/14 FG Missing People/slaveproductivity.dta", clear
drop ly   // E6: file was saved after an earlier run; line 5 regenerates ly identically
cd output
* ==== begin productivity.do lines 1-173 (verbatim) ====
H
sed -n '1,173p' productivity.do
cat <<'F'

* ==== end verbatim ====
cd ..
log close
F
} > run_productivity.do

# DIAGNOSTIC D1 (not a reproduction run): run_CreatingKhoe.do with line 8 "drop if district==0" disabled,
# to test whether the published Total rows (T1 slaves 1773/Total, T5 N=1096, T6 >5-slave N=432) come from a run without it.
sed -e 's#^drop if district==0$#* D1: line 8 disabled -- drop if district==0#' \
    -e 's#logs/run_CreatingKhoe.log#logs/diag_D1_keep_district0.log#' \
    -e 's#GENERATED by build_runs.sh#DIAGNOSTIC D1, GENERATED by build_runs.sh#' run_CreatingKhoe.do > diag_D1_keep_district0.do
